a{color:#8e2b22}a:hover{color:#5a1a14}
@keyframes drift{from{transform:translateX(0)}to{transform:translateX(-120px)}}
@keyframes drift2{from{transform:translateX(-160px)}to{transform:translateX(0)}}
@keyframes swell{0%,100%{transform:translateY(0)}50%{transform:translateY(4px)}}
@keyframes rain{from{transform:translate(0,-80px)}to{transform:translate(-26px,80px)}}
@keyframes glint{0%,100%{opacity:.15}50%{opacity:.55}}
.d1{animation:drift 10s linear infinite}
.d2{animation:drift2 16s linear infinite}
.sw{animation:swell 5s ease-in-out infinite}
.rn{animation:rain 1s linear infinite}
.rn2{animation:rain 1.3s linear infinite;animation-delay:-.5s}
.gl{animation:glint 3.5s ease-in-out infinite}
.mat{position:absolute;width:478px;background:radial-gradient(ellipse at 30% 20%,#f8f0de,#efe2c6 85%);border-radius:5px;box-shadow:0 1px 0 #c9b48c,0 3px 0 #a68f66,0 12px 20px rgba(0,0,0,.45);overflow:hidden}
.mat::after{content:"";position:absolute;inset:34px 4px 4px 4px;border:1px solid rgba(90,70,40,.35);border-radius:3px;pointer-events:none}
.mh{height:34px;display:flex;align-items:center;gap:8px;padding:0 6px 0 10px;color:#f6efe0;font-family:'Alegreya SC',serif;font-weight:800;font-size:17px;letter-spacing:.02em;box-shadow:inset 0 -2px 0 rgba(0,0,0,.25)}
.mh small{font-family:'Alegreya',serif;font-style:italic;font-weight:500;font-size:12.5px;opacity:.85;letter-spacing:0}
.mh .r{margin-left:auto;display:flex;align-items:center;gap:8px}
.fan{display:flex;align-items:center;gap:3px;font-family:'Alegreya Sans',sans-serif;font-size:12px;font-weight:800}
.fan i{display:inline-block;width:8px;height:11px;border-radius:1.5px;background:#3a2a10;box-shadow:0 0 0 1px #f6efe0;margin-right:-3px}
.leg{width:24px;height:24px;border-radius:50%;background:radial-gradient(circle at 34% 28%,#fff1b8 0,#e2bf62 30%,#a87c22 72%,#6e4e12 100%);box-shadow:inset 0 0 0 1.2px #4a340c,inset 0 0 0 2.6px rgba(255,236,170,.45),inset 0 0 0 3.4px rgba(74,52,12,.5),0 1px 2px rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center}
.body{position:relative;display:flex;gap:10px;padding:8px 12px 9px}
.rows{position:relative;z-index:1}
.rows{flex:1;display:flex;flex-direction:column;gap:6px;font-size:12.5px;color:#4a4036}
.row{display:flex;align-items:center;gap:8px}
.lbl{font-variant:small-caps;letter-spacing:.06em;font-weight:700;width:58px}
.row b{font-family:'Old Standard TT',serif;font-weight:700;color:#2a2521;font-size:13px}
.cells{display:flex;align-items:center;gap:1.5px}
.hc{display:inline-block;width:13px;height:13px;border-radius:2px 2px 6px 6px;background:linear-gradient(180deg,#b9824a 0 42%,#5b3a1c 42% 52%,#8e5d2e 52%);box-shadow:inset 0 0 0 1px #3a2412,0 1px 0 rgba(0,0,0,.2)}
.hc.x{position:relative;background:#e2d3b3;box-shadow:inset 0 0 0 1px #b9a27a}
.hc.x::after{content:"";position:absolute;left:6px;top:1px;width:1.6px;height:11px;background:#a3271d;transform:rotate(24deg)}
.sl{display:inline-block;position:relative;width:14px;height:16px;filter:drop-shadow(0 0 .5px #2a1a0c) drop-shadow(0 0 .5px #2a1a0c)}
.sl::before{content:"";position:absolute;left:1px;top:0;width:1.6px;height:16px;background:#3a2a1a}
.sl::after{content:"";position:absolute;left:2.6px;top:1px;width:11px;height:14px;background:linear-gradient(105deg,#fbf3df 0 30%,#e2cf9f 70%,#c7ac74);clip-path:polygon(0 0,100% 100%,0 100%)}
.sl.x{opacity:.22}
.gnx{opacity:.22}
.cr{display:inline-block;position:relative;width:12px;height:15px;background:radial-gradient(circle at 50% 40%,#e9c49e 0 3.6px,rgba(0,0,0,0) 3.9px),radial-gradient(ellipse 7px 6px at 50% 100%,#2f3e55 0 99%,rgba(0,0,0,0) 100%)}
.cr::before{content:"";position:absolute;left:2px;top:1.2px;width:8px;height:3.4px;border-radius:4px 4px 1px 1px;background:#a3271d}
.cr.x{background:radial-gradient(circle at 50% 45%,#d9d1c0 0 4.6px,rgba(0,0,0,0) 4.9px),radial-gradient(ellipse 3px 2px at 50% 88%,#d9d1c0 0 99%,rgba(0,0,0,0) 100%)}
.cr.x::before{left:2.2px;top:5px;width:8px;height:3px;border-radius:0;background:radial-gradient(circle at 22% 50%,#3a3530 0 1.3px,rgba(0,0,0,0) 1.5px),radial-gradient(circle at 78% 50%,#3a3530 0 1.3px,rgba(0,0,0,0) 1.5px)}
.grp{display:flex;align-items:center;gap:6px}
.grp + .grp{margin-left:10px;padding-left:10px;border-left:1px solid rgba(90,70,40,.3)}
.medal{width:86px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;font-size:11px;text-align:center;color:#4a4036;line-height:1.15;border-left:1px solid rgba(90,70,40,.3)}
.act{display:flex;gap:8px;padding:0 12px 10px}
.cmd{display:flex;align-items:center;gap:7px;height:34px;padding:0 12px;background:linear-gradient(#fbf5e7,#efe2c6);color:#2a2521;border:1.5px solid #2a2521;border-radius:4px;box-shadow:inset 0 0 0 2px #fbf5e7,inset 0 0 0 3px #6b5a40,0 2px 0 #a68f66;font-family:'Alegreya SC',serif;font-weight:800;font-size:14.5px;cursor:pointer}
.cmd .cost{display:flex;align-items:center;gap:3px;font-family:'Old Standard TT',serif;font-weight:700;padding-left:8px;border-left:1px solid #b9a27a}
.keg{display:inline-block;width:10px;height:13px;border-radius:3px;background:repeating-linear-gradient(90deg,#a06a36 0 3px,#7a4f24 3px 4px);box-shadow:inset 0 0 0 1px #3a2412,inset 0 3px 0 -1.5px #3a2412,inset 0 -3px 0 -1.5px #3a2412}
.cmd.dash{border-style:dashed;box-shadow:0 2px 0 #a68f66}
.card{position:absolute;width:118px;height:150px;background:linear-gradient(#fdf9f0,#f3ead6);border-radius:8px;box-shadow:0 1px 0 #d6c8ab,0 8px 14px rgba(0,0,0,.5);overflow:hidden;font-family:'Alegreya Sans',sans-serif;color:#2a2521}
.card::after{content:"";position:absolute;inset:23px 4px 4px 4px;border:1px solid rgba(90,70,40,.25);border-radius:4px}
.card .t{height:20px;color:#fff;font-size:10.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;display:flex;align-items:center;justify-content:space-between;padding:0 8px}
.card .n{font-family:'Old Standard TT',serif;font-weight:700;font-size:15px;line-height:1.12;padding:8px 9px 0;hyphens:auto}
.card .e{font-weight:800;font-size:13px;padding:4px 9px 0}
.card .x{font-size:11px;color:#5d5248;padding:4px 9px 0;line-height:1.25}
.glow{box-shadow:0 0 0 2px #e0bd62,0 0 16px rgba(255,196,120,.6),0 8px 14px rgba(0,0,0,.5)}
.ib{width:44px;height:44px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ead07c,#8f6b20 80%);border:0;box-shadow:inset 0 0 0 2px rgba(0,0,0,.3),inset 0 0 0 4px rgba(255,240,200,.25),0 3px 6px rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;cursor:pointer;color:#22180c}
.lg{display:grid;grid-template-columns:24px 1fr;gap:2px 8px;padding:6px 12px;border-bottom:1px solid #d6c6a3;font-size:13px;line-height:1.3;color:#3d342b}
.lg i{font-style:normal;font-family:'Old Standard TT',serif;font-weight:700;color:#8e2b22;font-size:12px}

